package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.shaded.org.mockito.Mockito.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.util.NoSuchElementException;
import java.util.function.Consumer;
import org.apache.commons.text.matcher.StringMatcher;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.evosuite.runtime.ViolatedAssumptionAnswer;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringTokenizer_ESTest_test01 extends StringTokenizer_ESTest_scaffolding {

    /**
     * Verifies the behaviour of a freshly created tokenizer whose delimiter
     * matcher never matches anything:
     * <ul>
     *   <li>{@link StringTokenizer#previousToken()} returns null when there is
     *       no token before the current position.</li>
     *   <li>{@link StringTokenizer#toString()} tokenizes the single-character
     *       input into one token and renders it as {@code StringTokenizer[...]}.</li>
     *   <li>{@link StringTokenizer#isIgnoreEmptyTokens()} keeps its documented
     *       default of {@code true}.</li>
     * </ul>
     */
    @Test(timeout = 4000)
    public void previousTokenReturnsNullAndToStringRendersSingleToken() throws Throwable {
        // Input is a one-character array holding the NUL character ('�').
        char[] input = new char[1];

        // A delimiter matcher that never matches, so the input stays a single token.
        StringMatcher neverMatchingDelimiter = mock(StringMatcher.class, new ViolatedAssumptionAnswer());
        doReturn((String) null, (String) null).when(neverMatchingDelimiter).toString();
        doReturn(0, 0).when(neverMatchingDelimiter).isMatch(any(char[].class), anyInt(), anyInt(), anyInt());

        StringTokenizer tokenizer = new StringTokenizer(input, neverMatchingDelimiter);

        // No token has been consumed yet, so there is no previous token.
        String previous = tokenizer.previousToken();
        assertNull(previous);

        // toString() triggers tokenization; the NUL character becomes the sole token.
        String rendered = tokenizer.toString();
        assertEquals("StringTokenizer[\\u0000]", rendered);

        // Ignoring empty tokens is the default behaviour.
        assertTrue(tokenizer.isIgnoreEmptyTokens());
    }
}
